import{signInWithEmailAndPassword}from"https://www.gstatic.com/firebasejs/9.23.0/firebase-auth.js";import{auth}from"./firebase.js";document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("loginForm"),e=document.getElementById("login-error");t.addEventListener("submit",async n=>{if(n.preventDefault(),e.textContent="",t.checkValidity()){const t=document.getElementById("email").value,n=document.getElementById("password").value,o=await signInWithEmailAndPassword(auth,t,n),a=await o.user.getIdToken(!0);await fetch("https://europe-central2-luxurystayskapanaplovdiv.cloudfunctions.net/api/login",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${a}`},body:JSON.stringify({})}).then(async t=>{if(t.ok)window.location.replace("control");else{const n=await t.text();e.textContent=`Login failed: ${n}`}}).catch(t=>{console.error(t),e.textContent=`Error: ${t.message}`})}})});